excels.excel:

EXPORT WITH SHEET="存货跌价准备计提表", HEADER=true,
    MAPPING={"a":"存货编码","b":"存货名称","c":"数量","d":"单位成本","e":"账面成本","f":"可变现净值","g":"跌价准备"},
    FORMAT={"c":"#,##0","d":"#,##0.00","e":"#,##0.00","f":"#,##0.00","g":"#,##0.00"},
    FORMULAS={
        E2:'C2*D2',G2:'E2-F2',
        E3:'C3*D3',G3:'E3-F3',
        E4:'C4*D4',G4:'E4-F4',
        E5:'C5*D5',G5:'E5-F5',
        E6:'C6*D6',G6:'E6-F6',
        E7:'SUM(E2:E6)',G7:'SUM(G2:G6)'
    },
    STYLE={
        ROW 7:{bold:true,fillPattern:solid_foreground,fillForegroundColor:lightYellow,alignment:right,verticalAlignment:center},
        G4:{color:red,bold:true}
    }
